WITH kept_keys AS (SELECT customer_id, id FROM subscriptions INTERSECT SELECT customer_id, id FROM subscriptions WHERE start_date <= '2024-12-01'), verified AS (SELECT s.* FROM subscriptions s INNER JOIN kept_keys k ON s.customer_id = k.customer_id AND s.id = k.id) SELECT s.customer_id, s.plan, s.end_date, s.status, (SELECT MIN(x.shipping_fee) FROM orders x WHERE x.customer_id = s.customer_id) AS min_order_shipping_fee FROM verified s
